import{_ as d,o as r,c as e,a4 as a}from"./chunks/framework.B7-9zdeN.js";const g=JSON.parse('{"title":"术语表","description":"按拼音排序的 Rust 核心术语中英文对照、一句话定义与首次出现章节","frontmatter":{"title":"术语表","description":"按拼音排序的 Rust 核心术语中英文对照、一句话定义与首次出现章节"},"headers":[],"relativePath":"appendix/glossary.md","filePath":"appendix/glossary.md","lastUpdated":1792644925000}'),i={name:"appendix/glossary.md"};function o(s,t,u,c,n,h){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h1><p>本表收录教程中反复出现的 44 个核心术语，按中文拼音首字母排序。定义只保留理解上下文所需的最少信息；「首次出现」链接到系统讲解该概念的章节。</p><ul><li>需要排查编译错误时，转到 <a href="/rust-tutorial-site/appendix/errors">常见错误速查</a>；</li><li>需要确认某个概念在第几章讲解时，用浏览器查找（<code>⌘/Ctrl + F</code>）或站内搜索；</li><li>英文名以官方文档与 <code>std</code> 中的写法为准，便于检索上游资料。</li></ul><h2 id="按主题索引" tabindex="-1">按主题索引 <a class="header-anchor" href="#按主题索引" aria-label="Permalink to &quot;按主题索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>相关术语</th></tr></thead><tbody><tr><td>内存与所有权</td><td>所有权、借用、可变引用、不可变引用、移动、克隆、栈、堆、生命周期、悬垂引用</td></tr><tr><td>类型与建模</td><td>结构体、枚举、元组、模式匹配、解构、切片</td></tr><tr><td>抽象与复用</td><td>特征、特征边界、特征对象、泛型、静态分派、动态分派、孤儿规则、宏、过程宏、unsafe</td></tr><tr><td>集合与迭代</td><td>迭代器、闭包</td></tr><tr><td>错误与数据交换</td><td>错误传播、序列化、反序列化</td></tr><tr><td>并发与异步</td><td>线程、互斥锁、数据竞争、消息传递、异步、运行时</td></tr><tr><td>智能指针</td><td>智能指针、引用计数、内部可变性</td></tr><tr><td>工程实践</td><td>单元测试、基准测试</td></tr></tbody></table><h2 id="术语列表" tabindex="-1">术语列表 <a class="header-anchor" href="#术语列表" aria-label="Permalink to &quot;术语列表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>拼音</th><th>一句话定义</th><th>首次出现</th></tr></thead><tbody><tr><td>闭包</td><td>closure</td><td>bì bāo</td><td>能捕获环境变量的匿名函数，可作为参数或返回值传递。</td><td><a href="/rust-tutorial-site/guide/06-collections">06 集合与迭代器</a></td></tr><tr><td>不可变引用</td><td>shared reference</td><td>bù kě biàn yǐn yòng</td><td>只读借用 <code>&amp;T</code>，同一作用域内可以同时存在多个。</td><td><a href="/rust-tutorial-site/guide/04-ownership">04 所有权</a></td></tr><tr><td>错误传播</td><td>error propagation</td><td>cuò wù chuán bō</td><td>用 <code>?</code> 把错误原样交给调用者，而不是就地处理。</td><td><a href="/rust-tutorial-site/guide/08-errors">08 错误处理</a></td></tr><tr><td>单元测试</td><td>unit test</td><td>dān yuán cè shì</td><td>与被测代码同文件、用 <code>#[test]</code> 标记的小粒度测试。</td><td><a href="/rust-tutorial-site/guide/13-testing">13 测试与文档</a></td></tr><tr><td>迭代器</td><td>iterator</td><td>dié dài qì</td><td>按需产出元素的对象，实现 <code>Iterator</code> 后可用于 <code>for</code> 与链式适配器。</td><td><a href="/rust-tutorial-site/guide/06-collections">06 集合与迭代器</a></td></tr><tr><td>动态分派</td><td>dynamic dispatch</td><td>dòng tài fēn pài</td><td>运行时经虚表决定调用哪个实现，代价是一次间接跳转。</td><td><a href="/rust-tutorial-site/guide/07-traits-generics">07 trait 与泛型</a></td></tr><tr><td>堆</td><td>heap</td><td>duī</td><td>运行时分配、生命周期不受栈帧约束的内存区域。</td><td><a href="/rust-tutorial-site/guide/09-smart-pointers">09 智能指针</a></td></tr><tr><td>泛型</td><td>generics</td><td>fàn xíng</td><td>用类型参数编写可复用代码，单态化后没有运行时开销。</td><td><a href="/rust-tutorial-site/guide/07-traits-generics">07 trait 与泛型</a></td></tr><tr><td>反序列化</td><td>deserialization</td><td>fǎn xù liè huà</td><td>把字节流或文本还原为内存中的数据结构。</td><td><a href="/rust-tutorial-site/guide/15-cli-project">15 实战：CLI 工具</a></td></tr><tr><td>孤儿规则</td><td>orphan rule</td><td>gū ér guī zé</td><td>只有当 trait 或类型至少一个属于当前 crate 时，才能实现该 trait。</td><td><a href="/rust-tutorial-site/guide/07-traits-generics">07 trait 与泛型</a></td></tr><tr><td>过程宏</td><td>procedural macro</td><td>guò chéng hóng</td><td>在编译期操作 <code>TokenStream</code> 生成代码的宏，分为派生、属性与函数式三类。</td><td><a href="/rust-tutorial-site/guide/12-macros-unsafe">12 宏、unsafe 与 FFI</a></td></tr><tr><td>宏</td><td>macro</td><td>hóng</td><td>编译期展开的代码生成机制，调用时名称后带 <code>!</code>。</td><td><a href="/rust-tutorial-site/guide/01-hello-rust">01 第一个 Rust 程序</a></td></tr><tr><td>互斥锁</td><td>mutex</td><td>hù chì suǒ</td><td>保证同一时刻只有一个线程访问共享数据的同步原语。</td><td><a href="/rust-tutorial-site/guide/10-concurrency">10 并发编程</a></td></tr><tr><td>基准测试</td><td>benchmark</td><td>jī zhǔn cè shì</td><td>测量代码执行时间与吞吐的测试，用于比较优化前后的差异。</td><td><a href="/rust-tutorial-site/guide/14-performance">14 性能优化</a></td></tr><tr><td>解构</td><td>destructuring</td><td>jiě gòu</td><td>用模式把结构体、枚举或元组拆成独立的字段绑定。</td><td><a href="/rust-tutorial-site/guide/05-structs-enums">05 结构体与枚举</a></td></tr><tr><td>结构体</td><td>struct</td><td>jié gòu tǐ</td><td>把一组命名字段组合成的新类型。</td><td><a href="/rust-tutorial-site/guide/05-structs-enums">05 结构体与枚举</a></td></tr><tr><td>借用</td><td>borrow</td><td>jiè yòng</td><td>不取得所有权而临时访问值，用 <code>&amp;</code> 或 <code>&amp;mut</code> 表示。</td><td><a href="/rust-tutorial-site/guide/04-ownership">04 所有权</a></td></tr><tr><td>静态分派</td><td>static dispatch</td><td>jìng tài fēn pài</td><td>编译期确定具体实现，泛型通过单态化达成。</td><td><a href="/rust-tutorial-site/guide/07-traits-generics">07 trait 与泛型</a></td></tr><tr><td>可变引用</td><td>mutable reference</td><td>kě biàn yǐn yòng</td><td>独占借用 <code>&amp;mut T</code>，同一作用域内只能存在一个。</td><td><a href="/rust-tutorial-site/guide/04-ownership">04 所有权</a></td></tr><tr><td>克隆</td><td>clone</td><td>kè lóng</td><td>通过 <code>.clone()</code> 显式复制值，通常伴随堆数据分配。</td><td><a href="/rust-tutorial-site/guide/04-ownership">04 所有权</a></td></tr><tr><td>枚举</td><td>enum</td><td>méi jǔ</td><td>由一组互斥变体构成的类型，每个变体可以携带数据。</td><td><a href="/rust-tutorial-site/guide/05-structs-enums">05 结构体与枚举</a></td></tr><tr><td>模块</td><td>module</td><td>mó kuài</td><td>用 <code>mod</code> 组织的命名空间与可见性边界。</td><td><a href="/rust-tutorial-site/guide/03-functions-modules">03 函数与模块</a></td></tr><tr><td>模式匹配</td><td>pattern matching</td><td>mó shì pǐ pèi</td><td>用 <code>match</code>、<code>if let</code> 等按结构拆解值并分支。</td><td><a href="/rust-tutorial-site/guide/05-structs-enums">05 结构体与枚举</a></td></tr><tr><td>内部可变性</td><td>interior mutability</td><td>nèi bù kě biàn xìng</td><td>通过 <code>Cell</code>、<code>RefCell</code> 在共享引用下修改数据。</td><td><a href="/rust-tutorial-site/guide/09-smart-pointers">09 智能指针</a></td></tr><tr><td>切片</td><td>slice</td><td>qiē piàn</td><td>对数组或字符串连续区间的借用视图，写作 <code>&amp;[T]</code> 或 <code>&amp;str</code>。</td><td><a href="/rust-tutorial-site/guide/06-collections">06 集合与迭代器</a></td></tr><tr><td>生命周期</td><td>lifetime</td><td>shēng mìng zhōu qī</td><td>编译器用于验证引用有效范围的标记，如 <code>&#39;a</code>。</td><td><a href="/rust-tutorial-site/guide/04-ownership">04 所有权</a></td></tr><tr><td>数据竞争</td><td>data race</td><td>shù jù jìng zhēng</td><td>多线程无同步地访问同一内存且至少有一次写入。</td><td><a href="/rust-tutorial-site/guide/10-concurrency">10 并发编程</a></td></tr><tr><td>所有权</td><td>ownership</td><td>suǒ yǒu quán</td><td>每个值有唯一所有者，所有者离开作用域时值被释放。</td><td><a href="/rust-tutorial-site/guide/04-ownership">04 所有权</a></td></tr><tr><td>特征</td><td>trait</td><td>tè zhēng</td><td>定义一组方法签名，描述类型可以提供的行为。</td><td><a href="/rust-tutorial-site/guide/07-traits-generics">07 trait 与泛型</a></td></tr><tr><td>特征边界</td><td>trait bound</td><td>tè zhēng biān jiè</td><td>对泛型参数施加的约束，如 <code>T: Display</code>。</td><td><a href="/rust-tutorial-site/guide/07-traits-generics">07 trait 与泛型</a></td></tr><tr><td>特征对象</td><td>trait object</td><td>tè zhēng duì xiàng</td><td><code>dyn Trait</code>，通过胖指针在运行时调用具体实现。</td><td><a href="/rust-tutorial-site/guide/07-traits-generics">07 trait 与泛型</a></td></tr><tr><td>unsafe</td><td>unsafe</td><td>unsafe</td><td>由程序员承担额外不变式、允许执行底层操作的标记。</td><td><a href="/rust-tutorial-site/guide/12-macros-unsafe">12 宏、unsafe 与 FFI</a></td></tr><tr><td>线程</td><td>thread</td><td>xiàn chéng</td><td>操作系统调度的执行单元，用 <code>std::thread::spawn</code> 创建。</td><td><a href="/rust-tutorial-site/guide/10-concurrency">10 并发编程</a></td></tr><tr><td>消息传递</td><td>message passing</td><td>xiāo xī chuán dì</td><td>线程间通过通道转移数据，而不是共享同一块内存。</td><td><a href="/rust-tutorial-site/guide/10-concurrency">10 并发编程</a></td></tr><tr><td>序列化</td><td>serialization</td><td>xù liè huà</td><td>把数据结构转换为可存储或传输的格式。</td><td><a href="/rust-tutorial-site/guide/15-cli-project">15 实战：CLI 工具</a></td></tr><tr><td>悬垂引用</td><td>dangling reference</td><td>xuán chuí yǐn yòng</td><td>指向已释放内存的引用，安全 Rust 中会被借用检查拒绝。</td><td><a href="/rust-tutorial-site/guide/04-ownership">04 所有权</a></td></tr><tr><td>异步</td><td>async</td><td>yì bù</td><td>用 <code>async</code>/<code>await</code> 表达可挂起的非阻塞任务。</td><td><a href="/rust-tutorial-site/guide/11-async">11 异步编程</a></td></tr><tr><td>移动</td><td>move</td><td>yí dòng</td><td>把值的所有权转移给另一个绑定，原绑定随即失效。</td><td><a href="/rust-tutorial-site/guide/04-ownership">04 所有权</a></td></tr><tr><td>引用</td><td>reference</td><td>yǐn yòng</td><td>不拥有值的间接访问，写作 <code>&amp;T</code> 或 <code>&amp;mut T</code>。</td><td><a href="/rust-tutorial-site/guide/04-ownership">04 所有权</a></td></tr><tr><td>引用计数</td><td>reference counting</td><td>yǐn yòng jì shù</td><td>通过计数共享所有权，<code>Rc</code>、<code>Arc</code> 在计数归零时释放值。</td><td><a href="/rust-tutorial-site/guide/09-smart-pointers">09 智能指针</a></td></tr><tr><td>元组</td><td>tuple</td><td>yuán zǔ</td><td>固定长度、元素类型可不同的匿名组合类型。</td><td><a href="/rust-tutorial-site/guide/02-variables-types">02 变量与类型</a></td></tr><tr><td>运行时</td><td>runtime</td><td>yùn xíng shí</td><td>驱动 <code>Future</code> 执行的执行器与调度器，如 tokio。</td><td><a href="/rust-tutorial-site/guide/11-async">11 异步编程</a></td></tr><tr><td>栈</td><td>stack</td><td>zhàn</td><td>存放函数局部变量与调用帧的后进先出内存区域。</td><td><a href="/rust-tutorial-site/guide/04-ownership">04 所有权</a></td></tr><tr><td>智能指针</td><td>smart pointer</td><td>zhì néng zhǐ zhēn</td><td>带所有权或额外语义的指针类型，如 <code>Box</code>、<code>Rc</code>、<code>Arc</code>。</td><td><a href="/rust-tutorial-site/guide/09-smart-pointers">09 智能指针</a></td></tr></tbody></table><h2 id="易混淆术语" tabindex="-1">易混淆术语 <a class="header-anchor" href="#易混淆术语" aria-label="Permalink to &quot;易混淆术语&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语对</th><th>区别</th></tr></thead><tbody><tr><td>移动与克隆</td><td>移动转移所有权且原绑定失效；克隆复制数据，两者随后都可使用。</td></tr><tr><td>可变引用与不可变引用</td><td>前者独占，同一作用域只能有一个；后者共享，可以同时存在多个。</td></tr><tr><td>特征边界与特征对象</td><td>边界约束泛型参数并在编译期单态化；对象使用 <code>dyn</code> 并在运行时查表。</td></tr><tr><td>静态分派与动态分派</td><td>前者在编译期确定实现；后者在运行时经虚表选择实现。</td></tr><tr><td><code>Rc</code> 与 <code>Arc</code></td><td>前者仅限单线程，计数操作无原子开销；后者可跨线程共享。</td></tr><tr><td>生命周期与作用域</td><td>作用域是变量可见的代码范围；生命周期是引用保持有效的区间，由编译器推导或标注。</td></tr></tbody></table><h2 id="常见符号" tabindex="-1">常见符号 <a class="header-anchor" href="#常见符号" aria-label="Permalink to &quot;常见符号&quot;">​</a></h2><table tabindex="0"><thead><tr><th>写法</th><th>含义</th><th>相关章节</th></tr></thead><tbody><tr><td><code>&amp;T</code></td><td>不可变引用，只读共享</td><td><a href="/rust-tutorial-site/guide/04-ownership">04 所有权</a></td></tr><tr><td><code>&amp;mut T</code></td><td>可变引用，独占访问</td><td><a href="/rust-tutorial-site/guide/04-ownership">04 所有权</a></td></tr><tr><td><code>T: Trait</code></td><td>泛型参数必须满足的特征边界</td><td><a href="/rust-tutorial-site/guide/07-traits-generics">07 trait 与泛型</a></td></tr><tr><td><code>dyn Trait</code></td><td>运行时确定实现的 trait 对象</td><td><a href="/rust-tutorial-site/guide/07-traits-generics">07 trait 与泛型</a></td></tr><tr><td><code>impl Trait</code></td><td>参数位置表示约束，返回位置表示隐藏的具体类型</td><td><a href="/rust-tutorial-site/guide/07-traits-generics">07 trait 与泛型</a></td></tr><tr><td><code>?</code></td><td>错误传播，失败时提前返回</td><td><a href="/rust-tutorial-site/guide/08-errors">08 错误处理</a></td></tr><tr><td><code>!</code></td><td>宏调用，如 <code>println!</code>、<code>vec!</code></td><td><a href="/rust-tutorial-site/guide/01-hello-rust">01 第一个 Rust 程序</a></td></tr><tr><td><code>&#39;_</code></td><td>匿名生命周期占位符，用于省略命名</td><td><a href="/rust-tutorial-site/guide/04-ownership">04 所有权</a></td></tr><tr><td><code>#[derive(...)]</code></td><td>让编译器自动生成 trait 实现</td><td><a href="/rust-tutorial-site/guide/05-structs-enums">05 结构体与枚举</a></td></tr></tbody></table><h2 id="维护约定" tabindex="-1">维护约定 <a class="header-anchor" href="#维护约定" aria-label="Permalink to &quot;维护约定&quot;">​</a></h2><p>新增术语时保持三列信息完整：中文名、英文名、首次出现章节；定义控制在 40 字以内，避免把整章的说明压缩进表格。若术语含义在后续章节扩展，保留首次出现链接，并在定义中补充使用边界。</p>',13)])])}const f=d(i,[["render",o]]);export{g as __pageData,f as default};
